STEP_WEIGHTS = [5, 15, 10, 50, 15, 5]
_last_sync_ts = 0.0
_last_sync_pct = -10

def log_progress(step_idx: int, code: str, stage_pct: int, msg: str, force: bool = False):
    global _last_sync_ts, _last_sync_pct
    stage_pct = max(0, min(100, int(stage_pct)))
    prev_weight = sum(STEP_WEIGHTS[:step_idx - 1])
    curr_weight = STEP_WEIGHTS[step_idx - 1]
    overall_pct = min(100, int(prev_weight + (curr_weight * stage_pct / 100.0)))
    ts = datetime.now().strftime("%H:%M:%S")
    line = f"[{ts}] TAHAP [{step_idx}/6] {code} ({stage_pct}% | Total: {overall_pct}%): {msg}"
    print(line, flush=True)

    now = time.time()
    if force or abs(overall_pct - _last_sync_pct) >= 5 or (now - _last_sync_ts) >= 15:
        _last_sync_ts = now
        _last_sync_pct = overall_pct
        try:
            os.makedirs(DRIVE_ROOT, exist_ok=True)
            with open(LIVE_LOG_FILE, "a", encoding="utf-8") as f:
                f.write(line + "\n")
            status_body = (
                f"STATUS: RUNNING\n"
                f"PROYEK: {JOB_TITLE}\n"
                f"PROGRES_TOTAL: {overall_pct}%\n"
                f"TAHAP_AKTIF: [{step_idx}/6] {code} ({stage_pct}%)\n"
                f"DETAIL: {msg}\n"
            )
            with open(STATUS_FILE, "w", encoding="utf-8") as f:
                f.write(status_body)
        except Exception:
            pass

def run_streaming(cmd, cwd=None, env=None, on_line=None, timeout=1800):
    proc = subprocess.Popen(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        bufsize=1,
        universal_newlines=False,
    )
    buf = bytearray()
    start_t = time.time()
    last_activity = start_t
    while True:
        if time.time() - start_t > timeout:
            proc.kill()
            raise TimeoutError(f"Perintah melebihi batas waktu {timeout}s: {' '.join(cmd)}")
        ch = proc.stdout.read(1) if proc.stdout else b""
        if not ch:
            if proc.poll() is not None:
                break
            time.sleep(0.05)
            continue
        last_activity = time.time()
        if ch in (b"\r", b"\n"):
            if buf:
                text_line = buf.decode("utf-8", errors="replace").strip()
                buf.clear()
                if text_line and on_line:
                    on_line(text_line)
        else:
            buf.extend(ch)
    if buf and on_line:
        on_line(buf.decode("utf-8", errors="replace").strip())
    rc = proc.wait()
    if rc != 0:
        raise RuntimeError(f"Perintah gagal (exit code {rc}): {' '.join(cmd)}")

def get_media_duration(path: str) -> float:
    out = subprocess.check_output(
        ["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "default=noprint_wrappers=1:nokey=1", path],
        text=True,
    ).strip()
    return float(out)

def generate_warm_pad_bgm(out_wav: str, duration_sec: float, sr: int = 48000):
    total_samples = int(duration_sec * sr)
    chords = [
        [130.81, 196.00, 246.94, 293.66],  # Cmaj9
        [110.00, 164.81, 196.00, 246.94],  # Am9
        [87.31, 130.81, 174.61, 220.00],   # Fmaj7
        [98.00, 146.83, 196.00, 220.00],   # G6
    ]
    chord_len = sr * 4
    with wave.open(out_wav, "w") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sr)
        chunk_size = 4096
        for start in range(0, total_samples, chunk_size):
            end = min(total_samples, start + chunk_size)
            frames = bytearray()
            for i in range(start, end):
                t = i / sr
                chord_idx = (i // chord_len) % len(chords)
                freqs = chords[chord_idx]
                local_pos = (i % chord_len) / chord_len
                env = math.sin(local_pos * math.pi) ** 0.35
                sample = 0.0
                for f in freqs:
                    sample += math.sin(2.0 * math.pi * f * t)
                val = int(max(-32767, min(32767, (sample / len(freqs)) * env * 14000)))
                frames.extend(struct.pack("<h", val))
            wf.writeframes(frames)

def generate_sfx_pack(sfx_dir: str, sr: int = 48000):
    os.makedirs(sfx_dir, exist_ok=True)
    # 1. whoosh.wav (0.40s)
    n = int(sr * 0.40)
    with wave.open(os.path.join(sfx_dir, "whoosh.wav"), "w") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sr)
        seed = 12345
        lp = 0.0
        buf = bytearray()
        for i in range(n):
            seed = (seed * 1103515245 + 12345) & 0x7FFFFFFF
            white = (seed / 0x3FFFFFFF) - 1.0
            lp = 0.85 * lp + 0.15 * white
            env = math.sin((i / n) * math.pi) ** 1.4
            val = int(max(-32767, min(32767, lp * env * 18000)))
            buf.extend(struct.pack("<h", val))
        wf.writeframes(buf)

    # 2. pop.wav (0.18s)
    n = int(sr * 0.18)
    with wave.open(os.path.join(sfx_dir, "pop.wav"), "w") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sr)
        buf = bytearray()
        for i in range(n):
            p = i / n
            freq = 520.0 * (1.0 - 0.65 * p)
            env = math.exp(-p * 7.0)
            val = int(max(-32767, min(32767, math.sin(2.0 * math.pi * freq * (i / sr)) * env * 20000)))
            buf.extend(struct.pack("<h", val))
        wf.writeframes(buf)

    # 3. tick.wav (0.12s)
    n = int(sr * 0.12)
    with wave.open(os.path.join(sfx_dir, "tick.wav"), "w") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sr)
        buf = bytearray()
        for i in range(n):
            p = i / n
            env = math.exp(-p * 14.0)
            val = int(max(-32767, min(32767, math.sin(2.0 * math.pi * 1100.0 * (i / sr)) * env * 18000)))
            buf.extend(struct.pack("<h", val))
        wf.writeframes(buf)

    # 4. chime.wav (0.32s)
    n = int(sr * 0.32)
    with wave.open(os.path.join(sfx_dir, "chime.wav"), "w") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sr)
        buf = bytearray()
        for i in range(n):
            t = i / sr
            p = i / n
            env = math.exp(-p * 5.0)
            sig = 0.6 * math.sin(2.0 * math.pi * 880.0 * t) + 0.4 * math.sin(2.0 * math.pi * 1318.5 * t)
            val = int(max(-32767, min(32767, sig * env * 18000)))
            buf.extend(struct.pack("<h", val))
        wf.writeframes(buf)

    # 5. thud.wav (0.24s)
    n = int(sr * 0.24)
    with wave.open(os.path.join(sfx_dir, "thud.wav"), "w") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sr)
        buf = bytearray()
        for i in range(n):
            p = i / n
            freq = 95.0 - 52.0 * p
            env = math.exp(-p * 6.5)
            val = int(max(-32767, min(32767, math.sin(2.0 * math.pi * freq * (i / sr)) * env * 22000)))
            buf.extend(struct.pack("<h", val))
        wf.writeframes(buf)

async def synthesize_all_segments(seg_dir: str):
    import edge_tts

    async def synth_one(idx: int, seg: dict):
        raw_mp3 = os.path.join(seg_dir, f"{seg['id']}_raw.mp3")
        clean_wav = os.path.join(seg_dir, f"{seg['id']}.wav")
        comm = edge_tts.Communicate(seg["text"], VOICE_NAME, rate=VOICE_RATE, pitch=VOICE_PITCH)
        boundaries = []
        with open(raw_mp3, "wb") as audio_fp:
            async for chunk in comm.stream():
                if chunk["type"] == "audio":
                    audio_fp.write(chunk["data"])
                elif chunk["type"] == "WordBoundary":
                    boundaries.append({
                        "word": chunk["text"],
                        "startSec": chunk["offset"] / 10_000_000.0,
                        "durSec": chunk["duration"] / 10_000_000.0,
                    })
        subprocess.run(
            ["ffmpeg", "-y", "-i", raw_mp3, "-ar", "48000", "-ac", "1", "-c:a", "pcm_s16le", clean_wav],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=True,
        )
        dur = get_media_duration(clean_wav)
        pct = int(((idx + 1) / len(SEGMENTS)) * 70)
        log_progress(2, "AUDIO", pct, f"Sintesis VO segmen {idx + 1}/{len(SEGMENTS)} selesai ({dur:.2f}s)")
        return {"id": seg["id"], "text": seg["text"], "wav": clean_wav, "duration": dur, "boundaries": boundaries}

    tasks = [synth_one(i, s) for i, s in enumerate(SEGMENTS)]
    return await asyncio.gather(*tasks)

